"""Shared fixtures for the tests and for manual runs. Uses only the SYNTHETIC data generated by sample_data/make_sample_data.py."""
from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

from ct_tool.extract import parse_gl, parse_tb          # noqa: E402
from ct_tool.fx import default_settings                  # noqa: E402
from ct_tool.pipeline import run_analysis                # noqa: E402
from ct_tool.project import Project                      # noqa: E402

GEN = ROOT / "sample_data" / "generated"
TEMPLATE = ROOT / "templates" / "Elitser_Holding_CT_Computation_FY_2025_TEMPLATE.xlsx"


def ensure_sample_data():
    if not (GEN / "Sample_TB_USD.xlsx").exists():
        sys.path.insert(0, str(ROOT / "sample_data"))
        import make_sample_data
        make_sample_data.main(["x", str(GEN)])


def make_project(ccy="USD", gl=True, rates=None) -> Project:
    ensure_sample_data()
    p = Project(name=f"Synthetic {ccy}")
    p.tb = parse_tb(str(GEN / f"Sample_TB_{ccy}.xlsx"), currency=ccy)
    if gl:
        p.gl = parse_gl(str(GEN / f"Sample_GL_{ccy}.xlsx"))
    p.fx = default_settings(ccy, "2025-01-01", "2025-12-31")
    if rates:
        p.fx.rates[ccy] = dict(rates)
        p.fx.method = "manual"
        p.fx.rate_source = "ILLUSTRATIVE rates used for testing only - not official"
        p.fx.method_reason = "Test"
    p.fx_confirmed = True
    return p


