def confirm_all(p: Project, an=None, override="Reviewer override for test"):
    an = an or run_analysis(p)
    for a in an.adjs:
        p.decisions[a.adj_id] = {"status": "Confirmed", "reviewer": "Test reviewer", "support_ref": "TEST", "override_note": override if a.blocking else ""}
    return run_analysis(p)


def make_scaled_project(tmp_dir, ccy="AED", scale=0.04, gl=True, rates=None) -> Project:
    """A smaller (or larger) synthetic company, written to tmp_dir - used for the Small Business Relief and loss tests."""
    sys.path.insert(0, str(ROOT / "sample_data"))
    import make_sample_data as M
    tmp_dir = Path(tmp_dir)
    tb, glines, _ = M.build(ccy, scale)
    M.write_tb_xlsx(tmp_dir / "tb.xlsx", tb, ccy)
    M.write_gl_xlsx(tmp_dir / "gl.xlsx", glines, ccy)
    p = Project(name=f"Scaled {ccy} {scale}")
    p.tb = parse_tb(str(tmp_dir / "tb.xlsx"), currency=ccy)
    if gl:
        p.gl = parse_gl(str(tmp_dir / "gl.xlsx"))
    p.fx = default_settings(ccy, "2025-01-01", "2025-12-31")
    if rates:
        p.fx.rates[ccy] = dict(rates)
        p.fx.method = "manual"
        p.fx.rate_source = "ILLUSTRATIVE test rates"
        p.fx.method_reason = "Test"
    p.fx_confirmed = True
    return p
